-- Script City: the client company. Generated by make_company.py, do not edit by hand.
CREATE TABLE departments (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT);

CREATE TABLE employees (id INTEGER PRIMARY KEY, name TEXT NOT NULL, role TEXT, dept_id INTEGER REFERENCES departments(id), manager_id INTEGER REFERENCES employees(id), salary INTEGER, hired TEXT);

CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT, email TEXT, joined TEXT, tier TEXT);

CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT, price REAL, stock INTEGER);

CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), rep_id INTEGER REFERENCES employees(id), ordered TEXT, status TEXT);

CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), product_id INTEGER REFERENCES products(id), qty INTEGER, unit_price REAL);

CREATE TABLE payments (id INTEGER PRIMARY KEY, order_id INTEGER REFERENCES orders(id), amount REAL, paid_on TEXT, method TEXT);

CREATE TABLE tickets (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), agent_id INTEGER REFERENCES employees(id), subject TEXT, priority TEXT, opened TEXT, closed TEXT);
